pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 putValue1, uint256 putValue2, uint256 collectAmt) public {
        // Restrict to admissible domain: unlockTime in future, values reasonable
        vm.assume(unlockTime > block.timestamp && unlockTime < type(uint64).max);
        vm.assume(putValue1 > 0 && putValue2 > 0 && putValue1 + putValue2 < type(uint128).max);
        vm.assume(collectAmt >= c.MinSum() && collectAmt <= putValue1 + putValue2);
        address actor = address(0x1234);
        vm.deal(actor, putValue1 + putValue2);

        // First Put with future unlockTime
        vm.prank(actor);
        c.Put{value: putValue1}(unlockTime);

        // Warp past unlockTime so original intent allows collect
        vm.warp(unlockTime + 1);

        // Second Put with no unlockTime extension (pass 0, which defaults to block.timestamp)
        vm.prank(actor);
        c.Put{value: putValue2}(0);

        // Now try to collect an amount >= MinSum and <= total balance
        bool ok;
        vm.prank(actor);
        try c.Collect{value: 0}(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: Collect must succeed when block.timestamp > acc.unlockTime, balance >= MinSum, balance >= amt.
        // In correct contract, first Put set unlockTime far in future, second preserved it, so it succeeds.
        // In mutant, second Put reset unlockTime to current block.timestamp (which equals warp time),
        // so block.timestamp > acc.unlockTime is false, causing Collect to revert.
        assertTrue(ok);
    }
}

