pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime1, uint256 unlockTime2, uint256 amount1, uint256 amount2, uint256 collectAmount) public {
        // Bind unlock times to be after 0 and not overflow block.timestamp for warp
        unlockTime1 = bound(unlockTime1, 1, type(uint256).max - 1000);
        unlockTime2 = bound(unlockTime2, unlockTime1 + 1000, type(uint256).max);
        // Bind amounts to be >0 and >= collectAmount
        amount1 = bound(amount1, 1 ether, 1000 ether);
        amount2 = bound(amount2, 1 ether, 1000 ether);
        collectAmount = bound(collectAmount, 1, amount1 + amount2);

        // Ensure amounts are >= collectAmount to satisfy Collect preconditions
        vm.assume(amount1 >= collectAmount);
        vm.assume(amount1 + amount2 >= collectAmount);

        address user = address(0xBEEF);
        vm.deal(user, amount1 + amount2);

        // First Put with later unlockTime
        vm.warp(1000);
        vm.prank(user);
        c.Put{value: amount1}(unlockTime2);

        // Second Put with earlier unlockTime (should update Acc[user].unlockTime in reference, but not in mutant)
        vm.warp(2000);
        vm.prank(user);
        c.Put{value: amount2}(unlockTime1);

        // Warp to a time after unlockTime1 but before unlockTime2
        uint256 collectTime = unlockTime1 + 1;
        vm.warp(collectTime);

        // In reference contract, unlockTime should be unlockTime1 (max of 2000 block.timestamp and unlockTime1)
        // and collect should succeed because block.timestamp > unlockTime.
        // In mutant, unlockTime is still unlockTime2, so Collect should revert.
        // After warping past unlockTime1, the reference contract allows Collect.
        bool ok;
        vm.prank(user);
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: Collect should succeed because unlockTime is updated to unlockTime1.
        // Mutant: Collect should fail because unlockTime remains unlockTime2 > block.timestamp.
        assertTrue(ok);
    }
}

