contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;
    function setUp() public {
        c = new C(address(this));
        attacker = new ReentrantAttacker(c);
    }
    function testFuzz_property(uint256 depositAmount, uint256 unlockTime, uint256 collectAmount) public {
        // Bound to usable ranges: deposit > 0, collect <= deposit, unlockTime in reasonable range
        vm.assume(depositAmount > 0);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);
        vm.assume(unlockTime > block.timestamp);
        // Fund attacker
        vm.deal(address(attacker), depositAmount);
        // Record expected balance after Put
        uint256 balanceBefore = address(c).balance;
        // Attack: reentrant Collect during Put's external call
        attacker.startAttack{value: depositAmount}(collectAmount);
        // The reference contract updates unlockTime in Put, so reentrant Collect cannot succeed
        // The mutant lacks unlockTime update, so unlockTime remains 0, allowing reentrant Collect
        // After the operation, the contract's ETH balance must equal the sum of collected amounts
        // In reference: only one Collect succeeds, balance = depositAmount - collectAmount
        // In mutant: two Collects succeed, balance = depositAmount - 2*collectAmount
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == depositAmount - collectAmount);
    }
}

