contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 value, uint256 unlockTime, uint256 initialBalance) public {
        // admissible domain: unlockTime > 0 (so it is not already zero) and value > 0 and no overflow
        vm.assume(unlockTime > 0);
        vm.assume(value > 0);
        bound(initialBalance, 0, type(uint256).max - value);
        bound(unlockTime, 1, type(uint256).max);

        // set initial balance through a first Put deposit
