        // make the Put call with a non-zero unlockTime
        c.Put{value: value}(unlockTime);

        // observe after
        (uint newUnlockTime, uint newBalance) = c.Acc(address(this));
        uint newSum = newBalance + newUnlockTime;

        // the sum must strictly increase because value > 0 and unlockTime >= block.timestamp >= prevUnlockTime
        // the bug sets unlockTime to 0, potentially making newSum <= prevSum
        assertTrue(newSum > prevSum);
