contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 putAmount, uint256 collectAmount, uint256 senderSeed) public {
        // Restrict to admissible domain: putAmount > 0, collectAmount <= putAmount, unlockTime > 0, senderSeed != address(0) and != this
        vm.assume(putAmount > 0);
        vm.assume(collectAmount <= putAmount);
        vm.assume(unlockTime > 0);
        address sender = address(uint160(uint256(keccak256(abi.encode(senderSeed)))));
