        vm.assume(sender != address(this));

        // Setup: sender puts ether and sets unlockTime
        vm.deal(sender, putAmount);
        vm.prank(sender);
        c.Put{value: putAmount}(unlockTime);

        // Ensure unlockTime has passed so only balance condition differs between versions
        vm.warp(unlockTime + 1);

        // Record balance before Collect
        uint256 balanceBefore = c.Acc(sender).balance;

        // Try Collect; C may revert if balance < MinSum, M may succeed
        bool ok;
        vm.prank(sender);
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }

        if (ok) {
            uint256 balanceAfter = c.Acc(sender).balance;
