            // The invariant: after a successful Collect, balanceAfter equals balanceBefore - collectAmount.
            assertTrue(balanceAfter == balanceBefore - collectAmount);
        } else {
            // In C, revert means no state change; balance remains.
            // In M, a revert due to external call failure (e.g., out of gas or failing transfer) would also leave balance unchanged,
            // but the bug does not introduce new revert behavior here; just ensure balance unchanged.
            assertTrue(c.Acc(sender).balance == balanceBefore);
        }
    }
