    constructor(C _c) { c = _c; }
    function run(address sender, uint256 unlockTime, uint256 putValue, uint256 collectAmt) public payable {
        require(address(this).balance >= putValue && putValue > 0 && collectAmt > 0);
        uint256 balBefore = address(c).balance;
        c.Put{value: putValue}(unlockTime);
        (uint256 balAfterPut, uint256 unlockAfter) = c.Acc(sender);
        require(balAfterPut > 0 && address(c).balance >= collectAmt && block.timestamp > unlockAfter && balAfterPut >= collectAmt && balAfterPut >= c.MinSum());
        c.Collect(collectAmt);
        assert(balAfterPut > 0 && address(c).balance >= collectAmt);
    }
    receive() external payable { }
}

