pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 _deposit, uint256 _collect, uint48 _unlockDelay) public {
        // Keep values in a wide admissible range; avoid overflows in deposit
        vm.assume(_deposit < type(uint256).max / 2 && _deposit >= 0);
        vm.assume(_collect < _deposit && _collect > 0);
        address actor = address(0x100);
        vm.deal(actor, _deposit);
        vm.startPrank(actor);
        c.Put{value: _deposit}(block.timestamp + _unlockDelay);
        vm.stopPrank();

        uint256 balBefore = c.Acc(actor).balance;

        vm.prank(actor);
        try c.Collect(_collect) {
            // on success the reference contract would only succeed if conditions hold;
            // the bug always succeeds. Check invariant: balance never increases.
            uint256 balAfter = c.Acc(actor).balance;
            assertTrue(balAfter <= balBefore);
        } catch {
            // revert is acceptable (reference may revert because conditions not met)
        }
    }
}

