pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _am, uint256 _deposit, address _actor) public {
        vm.assume(_actor != address(this));
        vm.assume(_am > 0);
        vm.assume(_deposit > 0);
        vm.deal(_actor, _deposit);
        vm.prank(_actor);
        c.Put{value: _deposit}(0);
        uint256 beforeBalance = c.Acc(_actor).balance;
        bool transferSucceeded;
        vm.prank(_actor);
        try c.Collect(_am) {
            transferSucceeded = true;
        } catch {
            transferSucceeded = false;
        }
        uint256 afterBalance = c.Acc(_actor).balance;
        if (!transferSucceeded) {
            assertTrue(afterBalance == beforeBalance);
        } else {
            assertTrue(true);
        }
    }
}

contract InvMutTest {
