    constructor(C _c) { c = _c; }

    function test(address sender, uint amount) public payable returns (bool) {
        require(address(this).balance >= amount);

        (bool s,) = address(c).call{value: amount}(abi.encodeWithSignature("Put(uint256)", block.timestamp + 1 days));
        require(s);

        bool revertCollect;
        (bool ok, bytes memory data) = address(c).call(abi.encodeWithSignature("Collect(uint256)", amount));
        revertCollect = !ok;

        assert(revertCollect == true);
    }
}

